def average_daily_demand(lines, case_sizes, sku, start_day, end_day):
    """Compute a SKU's average daily demand over a day range.

    Net demand is the total quantity shipped (SHP) minus the total quantity
    returned (RTN) for the SKU within [start_day, end_day] inclusive. The
    average daily demand is that net total divided by the number of days in
    the range, rounded up. If net demand is not positive, returns 0.
    """
    if end_day < start_day:
        raise ValueError("end_day is before start_day")
    net = 0
    for line in lines:
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        movement = parse_movement_line(text, case_sizes)
        if movement["sku"] != sku or not start_day <= movement["day"] <= end_day:
            continue
        if movement["type"] == "SHP":
            net += abs(movement["qty"])
        elif movement["type"] == "RTN":
            net -= abs(movement["qty"])
    if net <= 0:
        return 0
    days = end_day - start_day + 1
    return -(-net // days)
